<?php
require_once __DIR__.'/../config/auth.php';require_login();$id=user()['id'];
$f=db()->prepare('SELECT l.* FROM favoritos f JOIN livros l ON l.id=f.livro_id WHERE f.usuario_id=? ORDER BY f.created_at DESC');$f->execute([$id]);$favorites=$f->fetchAll();
$r=db()->prepare('SELECT r.*,l.titulo,l.quantidade_disponivel FROM reservas r JOIN livros l ON l.id=r.livro_id WHERE r.usuario_id=? ORDER BY r.created_at DESC');$r->execute([$id]);$reservations=$r->fetchAll();
if(isset($_GET['ler'])){db()->prepare('UPDATE notificacoes SET lida=1 WHERE usuario_id=?')->execute([$id]);redirect('aluno/central.php');}
$n=db()->prepare('SELECT * FROM notificacoes WHERE usuario_id=? ORDER BY created_at DESC LIMIT 20');$n->execute([$id]);$notes=$n->fetchAll();$pageTitle='Minha biblioteca';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';
?><div class="dashboard-cards"><section class="panel" style="margin:0"><h2>Favoritos</h2><?php foreach($favorites as $b):?><p><a href="<?=base_url('aluno/livro.php?id='.$b['id'])?>"><b><?=e($b['titulo'])?></b></a><br><small><?=e($b['autor'])?></small></p><?php endforeach;?><?php if(!$favorites):?><p class="subtext">Salve livros no catálogo para vê-los aqui.</p><?php endif;?></section><section class="panel" style="margin:0"><h2>Reservas</h2><?php foreach($reservations as $r):?><p><b><?=e($r['titulo'])?></b><br><span class="badge <?=$r['quantidade_disponivel']?'':'off'?>"><?=$r['quantidade_disponivel']?'Disponível — procure a biblioteca':'Na fila de espera'?></span></p><?php endforeach;?><?php if(!$reservations):?><p class="subtext">Nenhuma reserva em andamento.</p><?php endif;?></section><section class="panel" style="margin:0"><h2>Notificações</h2><a class="btn btn-small btn-outline" href="?ler=1">Marcar todas como lidas</a><?php foreach($notes as $n):?><p><b><?=e($n['titulo'])?></b><br><small><?=e($n['mensagem'])?></small></p><?php endforeach;?><?php if(!$notes):?><p class="subtext">Você não possui notificações.</p><?php endif;?></section></div><?php require __DIR__.'/../includes/dashboard-footer.php';?>
